def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    centers = [(r, c, grid[r][c]) for r in range(h) for c in range(w)
               if grid[r][c] not in (0, 3)]
    blank = []
    for r in range(1, h - 1):
        for c in range(1, w - 1):
            if grid[r][c] == 0 and grid[r-1][c] == grid[r+1][c] == 3 and grid[r][c-1] == grid[r][c+1] == 3:
                blank.append((r, c))
    blocked_rows = {r for r, c in blank}
    blocked_cols = {c for r, c in blank}
    for r, c, color in centers:
        if r not in blocked_rows:
            for x in range(w):
                if grid[r][x] == 0 and x not in blocked_cols:
                    out[r][x] = color
    for r, c, color in centers:
        if c not in blocked_cols:
            for y in range(h):
                if grid[y][c] == 0 and y not in blocked_rows:
                    out[y][c] = color
    return out
